package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.relatorio.RelatorioRepasseRepository; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Service public class RelatorioRepasseApplicationService { private final RelatorioRepasseRepository repo; private final SegurancaOrganizacaoService seguranca; public RelatorioRepasseApplicationService(RelatorioRepasseRepository r,SegurancaOrganizacaoService s){repo=r;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioRepasseItem> pesquisar(RelatorioRepasseFiltro f){validar(f);var p=repo.pesquisar(f.organizacaoUuid(),f.vencimentoInicio(),f.vencimentoFim(),status(f),f.somenteVencidos(),PageRequest.of(pagina(f),tamanho(f)));var itens=p.getContent().stream().map(x->new RelatorioRepasseItem(x.getUuid(),x.getVencimento(),x.getCompetencia(),x.getDestino(),x.getRegra(),nvl(x.getValorBase()),nvl(x.getValorExclusoes()),nvl(x.getValorDevido()),nvl(x.getValorPago()),nvl(x.getSaldo()),x.getStatus(),Boolean.TRUE.equals(x.getVencido()))).toList();return new RelatorioPagina<>(itens,pagina(f),tamanho(f),p.getTotalElements(),p.getTotalPages(),"vencimento","asc");}
 @Transactional(readOnly=true) public RelatorioRepasseResumo resumo(RelatorioRepasseFiltro f){validar(f);var r=repo.resumo(f.organizacaoUuid(),f.vencimentoInicio(),f.vencimentoFim(),status(f),f.somenteVencidos());return new RelatorioRepasseResumo(nvl(r.getTotalDevido()),nvl(r.getTotalPago()),nvl(r.getSaldoARepassar()));}
 private void validar(RelatorioRepasseFiltro f){if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória");if(f.vencimentoInicio()!=null&&f.vencimentoFim()!=null&&f.vencimentoFim().isBefore(f.vencimentoInicio()))throw new IllegalArgumentException("Vencimento final não pode ser anterior ao inicial");seguranca.validarAcesso(f.organizacaoUuid());} private String status(RelatorioRepasseFiltro f){return f.status()==null?null:f.status().name();} private int pagina(RelatorioRepasseFiltro f){return Math.max(0,f.pagina());} private int tamanho(RelatorioRepasseFiltro f){return Math.max(10,Math.min(100,f.tamanho()));} private BigDecimal nvl(BigDecimal v){return v==null?BigDecimal.ZERO:v;}
}
